{
  "correction_rules": [
    "Bias correction: Model consistently overestimates prices in early forecast periods; reduce initial forecast by 1-2% for 1-3 day horizons.",
    "Lag correction: Model lags behind true price movements by 2-5 days; adjust forecast to align with recent 3-5 day true price trend.",
    "Overshoot after spikes: After sharp price spikes (e.g., >5% from prior day), reduce forecast by 3-5% to avoid overcorrection.",
    "Mean reversion: If price deviates >3% from 14-day moving average, apply mean reversion adjustment toward the average.",
    "Sentiment-driven bias: When sentiment >0.25, model tends to overreact; reduce forecast by 1-3% for sentiment >0.25 and adjust downward if sentiment is rising.",
    "Horizon-specific: For 30-day forecasts, model overestimates near-term (1-7 day) prices; apply downward adjustment of 1-3% for short-term horizons."
  ]
}
